<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Services\Support;
class AppealController extends Controller {
 private function applicant(){ $u=auth()->user();abort_unless(in_array($u->role,['buyer','seller'])&&$u->account_status==='suspended',403);return $u; }
 public function form(){ $u=$this->applicant();if(request()->expectsJson())return response()->json(['account_status'=>'suspended','reason'=>$u->account_status_reason,'appeals'=>DB::table('account_appeals')->where('user_id',$u->id)->orderByDesc('id')->get()]);return view('appeal',['user'=>$u,'appeals'=>DB::table('account_appeals')->where('user_id',$u->id)->orderByDesc('id')->get()]); }
 public function submit(Request $r){$u=$this->applicant();$v=$r->validate(['message'=>'required|string|min:20|max:3000']);DB::transaction(function()use($u,$v){$locked=DB::table('users')->where('id',$u->id)->lockForUpdate()->first();abort_unless($locked->account_status==='suspended',403);if(DB::table('account_appeals')->where('user_id',$u->id)->where('status','pending')->exists())Support::fail('message','You already have a pending appeal.');DB::table('account_appeals')->insert($v+['user_id'=>$u->id,'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);Support::notify(DB::table('users')->where('role','admin')->pluck('id')->all(),'A suspended account submitted an appeal. Review Admin > Appeals.');});return $r->expectsJson()?response()->json(['message'=>'Your appeal was sent to the administrator.']):back()->with('success','Your appeal was sent to the administrator.');}
 public function index(){return view('admin_appeals',['links'=>app(CommonController::class)->links(),'appeals'=>DB::table('account_appeals as a')->join('users as u','u.id','=','a.user_id')->select('a.*','u.name','u.role','u.account_status')->orderByDesc('a.id')->paginate(30)]);}
 public function resolve(Request $r,int $id){$v=$r->validate(['decision'=>'required|in:approved,rejected','resolution'=>'required|string|min:5|max:3000']);DB::transaction(function()use($id,$v){$a=DB::table('account_appeals')->find($id);abort_unless($a,404);$u=DB::table('users')->where('id',$a->user_id)->lockForUpdate()->first();$a=DB::table('account_appeals')->where('id',$id)->lockForUpdate()->first();abort_unless($a->status==='pending'&&$u->account_status==='suspended',422,'Only a suspended account with a pending appeal can be reviewed.');DB::table('account_appeals')->where('id',$id)->update(['status'=>$v['decision'],'resolution'=>$v['resolution'],'updated_at'=>now()]);if($v['decision']==='approved')DB::table('users')->where('id',$u->id)->update(['active'=>1,'account_status'=>'active','account_status_reason'=>$v['resolution'],'updated_at'=>now()]);Support::audit('account-appeal','user',$u->id,$u,$v,$v['resolution']);Support::notify([$u->id],'Your appeal was '.$v['decision'].': '.$v['resolution']);Support::email($u->id,'LokaShop appeal decision','Your appeal was '.$v['decision'].'. '.$v['resolution']);});return back()->with('success','Appeal decision saved.');}
}
